INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at, created_at, updated_at) VALUES ('f67c01df-9ad1-4e48-94c4-bb9841ee9bf4', 'albania-praias-e-cidades-historicas', 'published', 'europa', 'Albânia: praias de água clara e cidades históricas longe das multidões', 'longe das multidões', 'Riviera Albanesa, Butrint, Berat e Gjirokastër: por que a Albânia entrou no roteiro de quem já conhece o básico da Europa.', 'Mar Jônico cor de piscina, cidades de pedra e montanhas: a Albânia é a Europa que ainda surpreende.', 'Albânia', NULL, '/assets/blog/albania.jpg', '/assets/blog/albania-m.jpg', 'Litoral da Albânia com água cristalina, um veleiro e um posto de salva-vidas', 1, '[{"t":"p","text":"A Albânia fica nos Bálcãs, entre Montenegro, Kosovo, Macedônia do Norte e Grécia, com litoral no Mar Adriático e no Mar Jônico. Durante décadas ficou fora do radar dos viajantes, e é justamente isso que atrai hoje: praias de água clara, história de mais de dois mil anos e um ritmo mais tranquilo do que o dos vizinhos mais famosos."},{"t":"h","label":"01","text":"A Riviera Albanesa"},{"t":"p","text":"O trecho de litoral entre Vlorë e Sarandë concentra as praias mais bonitas do país. Algumas paradas que valem o caminho:"},{"t":"ul","items":["**Ksamil:** pequenas ilhas a poucos metros da areia e água transparente. É a praia mais procurada, então vale chegar cedo na alta temporada.","**Sarandë:** cidade com boa estrutura de hotéis e restaurantes, uma ótima base para explorar o sul.","**Himarë e Dhërmi:** vilas com praias de pedrinhas e mar muito azul, mais tranquilas que Ksamil."]},{"t":"h","label":"02","text":"Butrint, uma cidade de muitas épocas"},{"t":"p","text":"Perto de Ksamil fica o Parque Nacional de Butrint, sítio arqueológico declarado Patrimônio Mundial pela UNESCO. Em meio ao verde há ruínas gregas, romanas, bizantinas e venezianas, incluindo um teatro antigo. Reserve algumas horas e leve água: quase toda a visita é ao ar livre."},{"t":"h","label":"03","text":"Berat e Gjirokastër"},{"t":"p","text":"As duas cidades formam, juntas, um Patrimônio Mundial da UNESCO e guardam a arquitetura do período otomano. Berat é conhecida como a cidade das mil janelas, pelas casas brancas empilhadas na encosta. Gjirokastër tem ruas de pedra, telhados de lajes cinzentas e um castelo no alto, com vista para o vale."},{"t":"h","label":"04","text":"Tirana e as montanhas"},{"t":"p","text":"A capital, Tirana, é colorida e animada, com cafés, a Praça Skanderbeg e o Bunk''Art, museu instalado num antigo bunker da Guerra Fria. Para quem gosta de natureza, os Alpes Albaneses, no norte, têm trilhas famosas, como a que liga Valbona a Theth."},{"t":"tip","title":"Dicas práticas","items":["**Quando ir:** junho e setembro costumam ter mar quente e menos gente do que julho e agosto.","**Como chegar:** o principal aeroporto é o de Tirana. No sul, ferries ligam a ilha grega de Corfu a Sarandë, uma boa combinação para quem já está na Grécia.","**Como circular:** carro alugado dá liberdade para percorrer a Riviera. As estradas de montanha pedem calma e tempo.","**Dinheiro:** a moeda é o lek. Em áreas turísticas às vezes aceitam euro, mas o troco costuma vir em lek.","**Entrada:** a Albânia não faz parte do espaço Schengen e tem regras próprias. Confira o que vale para o seu passaporte nos canais oficiais antes de viajar."]}]', 6, '2026-09-29 12:00:00', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at, created_at, updated_at) VALUES ('b151b5f5-44bf-4484-b315-22b90e3afd26', 'lisboa-em-3-dias', 'published', 'portugal', 'Lisboa em 3 dias: bairros, miradouros e o que não pode faltar', 'não pode faltar', 'Alfama, Belém, Chiado e um pôr do sol num miradouro: o essencial de Lisboa num roteiro possível.', 'Alfama, Belém, Chiado e um pôr do sol num miradouro: o essencial de Lisboa num roteiro possível.', 'Lisboa', NULL, '/assets/blog/lisboa.jpg', '/assets/blog/lisboa-m.jpg', 'Telhados vermelhos da Alfama, em Lisboa, com o rio Tejo ao fundo', 0, '[{"t":"p","text":"Lisboa é uma cidade de colinas, luz e elétricos amarelos. É também uma das capitais europeias onde a gente se sente em casa com mais facilidade: a língua ajuda, a comida conforta e cada miradouro parece feito para o fim de tarde."},{"t":"h","label":"Dia 1","text":"Baixa, Chiado e Alfama"},{"t":"p","text":"Comece pela **Praça do Comércio** e suba a Rua Augusta até o Rossio. O **Elevador de Santa Justa** leva ao Carmo e ao **Chiado**, bairro de cafés e livrarias. À tarde, suba até a **Alfama**: a Sé de Lisboa, os miradouros de Santa Luzia e das Portas do Sol e o **Castelo de São Jorge**. À noite, fado na Alfama ou na Mouraria."},{"t":"h","label":"Dia 2","text":"Belém e LX Factory"},{"t":"p","text":"Em Belém ficam a **Torre de Belém** e o **Mosteiro dos Jerónimos**, ambos Patrimônio Mundial da UNESCO, além do Padrão dos Descobrimentos. Os pastéis de Belém, servidos quentes com canela, são parada obrigatória. No fim da tarde, a **LX Factory**, antiga fábrica transformada em espaço de lojas e restaurantes, fica no caminho de volta ao centro."},{"t":"h","label":"Dia 3","text":"Sintra"},{"t":"p","text":"Os trens para **Sintra** saem da estação do Rossio, e a viagem é curta. Por lá, o **Palácio da Pena**, colorido no alto da serra, e a **Quinta da Regaleira**, com jardins e o famoso poço iniciático, ocupam o dia inteiro. Na alta temporada, compre os ingressos com antecedência."},{"t":"h","label":"Extra","text":"Miradouros para o pôr do sol"},{"t":"p","text":"Além de Santa Luzia e Portas do Sol, vale subir ao **Miradouro da Senhora do Monte**, um dos pontos mais altos da cidade, ao da **Graça** e ao de **São Pedro de Alcântara**, no Bairro Alto."},{"t":"tip","title":"Dicas práticas","items":["**Elétrico 28:** passa pelos bairros mais bonitos, mas lota. Vá cedo.","**Transporte:** o cartão Viva Viagem é recarregável e vale para metrô, elétricos, ônibus e trens urbanos.","**Sapatos:** a calçada portuguesa é linda e escorregadia, principalmente nas ladeiras e em dia de chuva.","**Onde ficar:** Baixa e Chiado para fazer muita coisa a pé; Príncipe Real e Avenida da Liberdade para algo mais tranquilo."]}]', 5, '2026-09-29 12:00:00', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at, created_at, updated_at) VALUES ('4982ba55-708f-48ac-899c-c59bd1bd51e1', 'roma-em-4-dias', 'published', 'europa', 'Roma em 4 dias: roteiro para a primeira viagem', 'primeira viagem', 'Coliseu, Vaticano, praças e fontes: um roteiro possível, sem correria, para conhecer o essencial da Cidade Eterna.', 'Coliseu, Vaticano, praças e fontes: um roteiro possível, sem correria, para conhecer o essencial da Cidade Eterna.', 'Roma', NULL, '/assets/blog/roma.jpg', '/assets/blog/roma-m.jpg', 'Coliseu de Roma ao pôr do sol, emoldurado por árvores', 0, '[{"t":"p","text":"Roma é uma cidade para caminhar. Boa parte do centro histórico cabe em trajetos a pé, e cada esquina guarda uma igreja, uma praça ou uma ruína com dois mil anos de história. Em quatro dias dá para ver o essencial com calma, desde que os ingressos principais estejam reservados antes."},{"t":"h","label":"Dia 1","text":"Roma Antiga"},{"t":"p","text":"Comece pelo **Coliseu**, pelo **Fórum Romano** e pelo **Monte Palatino**, que ficam lado a lado e costumam ser visitados com o mesmo ingresso. Reserve horário no site oficial, principalmente na alta temporada. No fim da tarde, caminhe até a Piazza Venezia e o Vittoriano, monumento com um terraço panorâmico sobre a cidade."},{"t":"h","label":"Dia 2","text":"Vaticano"},{"t":"p","text":"Os **Museus Vaticanos** terminam na **Capela Sistina**, e a visita pode levar a manhã inteira. Depois, siga para a **Basílica de São Pedro** e a praça em frente. Quem tiver fôlego pode subir à cúpula, que tem uma das vistas mais bonitas de Roma. Nas igrejas e no Vaticano, ombros e joelhos precisam estar cobertos. À tarde, desça a Via della Conciliazione até o **Castel Sant''Angelo**, às margens do rio Tibre."},{"t":"h","label":"Dia 3","text":"Centro histórico"},{"t":"p","text":"Um dia para andar sem pressa entre o **Panteão**, a **Piazza Navona**, o mercado do **Campo de'' Fiori**, a **Fontana di Trevi** e a **Escadaria da Praça de Espanha**. Na Fontana di Trevi, a tradição manda jogar uma moeda de costas para garantir a volta a Roma. Na Escadaria, não é permitido sentar nos degraus."},{"t":"h","label":"Dia 4","text":"Villa Borghese e Trastevere"},{"t":"p","text":"Pela manhã, visite a **Galleria Borghese**, com obras de Bernini e Caravaggio, que só recebe visitantes com reserva. Depois, passeie pelo parque da Villa Borghese e siga até o Pincio para ver a Piazza del Popolo do alto. Termine o dia no **Trastevere**, bairro de ruelas e restaurantes do outro lado do rio."},{"t":"tip","title":"Dicas práticas","items":["**Reservas:** Coliseu, Museus Vaticanos e Galleria Borghese têm vagas por horário. Compre nos sites oficiais e desconfie de revendas com preço inflado.","**Água:** Roma tem bebedouros públicos, os nasoni, com água potável. Leve uma garrafa.","**Sapatos:** o calçamento de pedra cansa. Um tênis confortável faz diferença.","**Quando ir:** primavera e outono costumam ser mais agradáveis. No verão, evite as horas mais quentes do dia.","**Onde ficar:** perto da Piazza Navona ou do Panteão para fazer quase tudo a pé; no Trastevere para jantar perto do hotel; perto da estação Termini para ter mais opções de transporte."]}]', 6, '2026-09-29 12:00:00', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at, created_at, updated_at) VALUES ('5a080905-1de9-4145-b829-53cb5c7f9a20', 'voltar-ao-brasil-nas-ferias', 'published', 'brasil', 'Voltar ao Brasil nas férias: como planejar a viagem saindo de Portugal', 'saindo de Portugal', 'Datas, rotas, bagagem, documentos e milhas: um guia para quem mora em Portugal e quer rever a família no Brasil sem sustos.', 'Datas, rotas, bagagem, documentos e milhas: um guia para quem mora em Portugal e quer rever a família no Brasil sem sustos.', 'Brasil', 'Vai voltar ao Brasil?', '/assets/blog/brasil.jpg', '/assets/blog/brasil-m.jpg', 'Vista do alto do Rio de Janeiro, com o Pão de Açúcar e a baía de Guanabara', 0, '[{"t":"p","text":"Para quem mora em Portugal, a viagem ao Brasil é mais do que férias: é reencontro. Justamente por isso, costuma cair nas mesmas datas que todo mundo escolhe. Planejar com antecedência faz diferença no preço, no conforto e na tranquilidade."},{"t":"h","label":"01","text":"Quando comprar"},{"t":"p","text":"Dezembro, janeiro e julho estão entre as épocas mais procuradas, por causa do fim de ano e das férias escolares. Nessas datas, os voos lotam cedo. Comprar com meses de antecedência e ter alguma flexibilidade, nem que seja de um ou dois dias, ajuda a encontrar opções melhores."},{"t":"h","label":"02","text":"Direto ou com conexão"},{"t":"p","text":"Lisboa tem voos diretos para várias capitais brasileiras. Saindo do Porto, ou quando o destino final é uma cidade menor, as conexões ampliam as opções. Um voo com conexão pode sair mais em conta, mas compare o tempo total de viagem, principalmente com crianças ou idosos."},{"t":"h","label":"03","text":"As milhas contam muito"},{"t":"p","text":"Em datas concorridas, usar milhas pode reduzir bastante o custo da passagem. Na Rota Certa, a proposta de voo pode vir em dinheiro, em milhas ou nos dois formatos, para você comparar e escolher."},{"t":"h","label":"04","text":"Bagagem sem sustos"},{"t":"ul","items":["A franquia muda conforme a companhia e a tarifa. Algumas tarifas mais baratas não incluem mala despachada.","Pese as malas antes de sair de casa: presentes e encomendas da família costumam pesar mais do que parece.","Alimentos têm regras de entrada, tanto no Brasil quanto na União Europeia, especialmente os de origem animal. Confira antes de colocar na mala."]},{"t":"h","label":"05","text":"Documentos"},{"t":"ul","items":["Passaporte válido para toda a viagem.","Para quem mora em Portugal, o título ou cartão de residência válido, para voltar sem problemas.","Crianças e adolescentes que viajam sem os dois responsáveis podem precisar de autorização. Confira as exigências antes de comprar a passagem."]},{"t":"tip","title":"Checklist rápido","items":["Datas definidas, com alguma flexibilidade","Voo direto e com conexão comparados","Cotação em dinheiro e em milhas","Franquia de bagagem conferida na tarifa","Passaporte e residência válidos"]}]', 5, '2026-09-29 12:00:00', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at, created_at, updated_at) VALUES ('e3943ff9-5684-410d-b22b-7b39fd86daa7', 'paris-primeira-viagem', 'published', 'europa', 'Paris na primeira viagem: o que ver e como se organizar', 'como se organizar', 'Torre Eiffel, Louvre, Montmartre e o Sena: um guia para aproveitar Paris sem perder tempo em filas.', 'Torre Eiffel, Louvre, Montmartre e o Sena: um guia para aproveitar Paris sem perder tempo em filas.', 'Paris', NULL, '/assets/blog/paris.jpg', '/assets/blog/paris-m.jpg', 'Rio Sena ao entardecer em Paris, com barcos e pontes', 0, '[{"t":"p","text":"Paris recompensa quem se organiza. Os monumentos mais famosos vendem ingressos com hora marcada, e alguns fecham em dias fixos da semana. Com um pouco de planejamento, sobra tempo para o que a cidade tem de melhor: caminhar sem rumo, sentar num café e ver o Sena ao entardecer."},{"t":"h","label":"01","text":"O essencial"},{"t":"ul","items":["**Torre Eiffel:** suba no fim da tarde para ver a cidade de dia e acesa. Os ingressos com hora marcada são vendidos no site oficial.","**Louvre:** reserve horário e escolha algumas alas, porque é impossível ver tudo de uma vez. O museu fecha às terças-feiras.","**Museu d''Orsay:** o endereço dos impressionistas, dentro de uma antiga estação de trem. Fecha às segundas-feiras.","**Île de la Cité:** a Catedral de Notre-Dame, reaberta em dezembro de 2024 depois do incêndio de 2019, e a Sainte-Chapelle, famosa pelos vitrais.","**Montmartre:** ruas em ladeira, artistas na Place du Tertre e a vista da Basílica de Sacré-Cœur."]},{"t":"h","label":"02","text":"Um roteiro de 4 dias"},{"t":"ul","items":["**Dia 1:** Torre Eiffel, Trocadéro e um passeio de barco pelo Sena.","**Dia 2:** Louvre, Jardim das Tulherias e Champs-Élysées até o Arco do Triunfo.","**Dia 3:** Notre-Dame, Sainte-Chapelle e o bairro do Marais.","**Dia 4:** Montmartre pela manhã e Museu d''Orsay à tarde, lembrando que ele fecha às segundas."]},{"t":"p","text":"Com um dia a mais, vale o bate e volta ao **Palácio de Versalhes**, que também fecha às segundas-feiras."},{"t":"h","label":"03","text":"Onde ficar"},{"t":"p","text":"O **Marais** é central, charmoso e cheio de restaurantes. **Saint-Germain-des-Prés** e o **Quartier Latin** ficam na margem esquerda, com livrarias e cafés clássicos. Perto da Torre Eiffel as noites são mais tranquilas, mas você vai depender mais do metrô."},{"t":"tip","title":"Dicas práticas","items":["**Metrô:** cobre a cidade inteira e é o jeito mais rápido de circular entre bairros distantes.","**Museus:** se for visitar muitos museus, compare o preço dos ingressos avulsos com o Paris Museum Pass.","**Atenção:** em áreas turísticas e no metrô, cuidado com batedores de carteira.","**Educação:** um \"bonjour\" ao entrar em lojas e restaurantes muda o atendimento."]}]', 6, '2026-09-29 12:00:00', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes, published_at, created_at, updated_at) VALUES ('38a8905d-0879-4745-8c98-81ee0b64d8f4', 'istambul-primeira-visita', 'published', 'europa', 'Istambul entre dois continentes: guia da primeira visita', 'dois continentes', 'Mesquitas, bazares e o Bósforo: como aproveitar a cidade onde a Europa encontra a Ásia.', 'Mesquitas, bazares e o Bósforo: como aproveitar a cidade onde a Europa encontra a Ásia.', 'Istambul', NULL, '/assets/blog/istambul.jpg', '/assets/blog/istambul-m.jpg', 'Mesquita de Ortaköy à beira do Bósforo, com a ponte ao fundo, em Istambul', 0, '[{"t":"p","text":"Istambul fica dos dois lados do Estreito do Bósforo, com uma parte na Europa e outra na Ásia. Foi capital de impérios por mais de 1.500 anos, e isso aparece em cada esquina: mesquitas, palácios, bazares e uma vida de rua intensa, que vai até tarde da noite."},{"t":"h","label":"01","text":"Sultanahmet, o centro histórico"},{"t":"p","text":"Os monumentos mais famosos ficam perto uns dos outros:"},{"t":"ul","items":["**Santa Sofia:** construída como basílica no século VI, hoje funciona como mesquita. Turistas têm horários e regras próprias de visita, então confira antes de ir.","**Mesquita Azul:** oficialmente Mesquita do Sultão Ahmed, famosa pelos azulejos azuis do interior.","**Cisterna da Basílica:** um reservatório subterrâneo da época bizantina, com centenas de colunas.","**Palácio de Topkapi:** residência dos sultões otomanos durante séculos, com pátios, joias e vista para o Bósforo."]},{"t":"h","label":"02","text":"Bazares"},{"t":"p","text":"O **Grande Bazar** é um dos maiores mercados cobertos do mundo, com milhares de lojas. O **Bazar das Especiarias**, perto do porto de Eminönü, é o lugar de chás, doces e temperos. Nos dois, pechinchar faz parte da conversa."},{"t":"h","label":"03","text":"O Bósforo e o lado asiático"},{"t":"p","text":"Um passeio de barco pelo Bósforo mostra palácios, casarões à beira d''água e a mesquita de Ortaköy sob a ponte. Os ferries públicos também são um jeito simples de cruzar para o lado asiático, até bairros como **Kadıköy** e **Üsküdar**, com mercados e restaurantes frequentados pelos moradores."},{"t":"h","label":"04","text":"Gálata e Beyoğlu"},{"t":"p","text":"Do outro lado do Chifre de Ouro, a **Torre de Gálata** tem vista para toda a cidade, e a **Avenida Istiklal**, só para pedestres, é percorrida por um bonde histórico."},{"t":"tip","title":"Dicas práticas","items":["**Nas mesquitas:** ombros e joelhos cobertos, sapatos fora e, para mulheres, cabelo coberto. As visitas pausam nos horários de oração.","**Transporte:** o cartão Istanbulkart vale para metrô, bonde, ônibus e ferries.","**Aeroportos:** a cidade tem dois. O Aeroporto de Istambul (IST) fica do lado europeu, e o Sabiha Gökçen (SAW), do lado asiático. Confira qual é o do seu voo.","**Entrada:** confira as regras de entrada na Turquia para o seu passaporte nos canais oficiais antes de viajar."]}]', 6, '2026-09-29 12:00:00', '2026-09-29 12:00:00', '2026-09-29 12:00:00');
